int pts[] = primpoints(0, @primnum);
addprim(0, "polyline", pts[0], pts[2]);
addprim(0, "polyline", pts[1], pts[3]);

int chip_count = nprimitives(1);
int current_chip_id = -1;

for(int i = 0; i < chip_count; i++){
    int chip_corners[] = primpoints(1, i);
    vector min_bounds, max_bounds;
    getbbox(1, itoa(i), min_bounds, max_bounds);
    float eps = 0.001;

    if (@P.x > min_bounds.x + eps && @P.x <= max_bounds.x + eps &&
        @P.z > min_bounds.z + eps && @P.z <= max_bounds.z + eps) {

        @group_chip = 1;
        i@chip_id = prim(1, "chip_id", i);
        s@chip_type = prim(1, "chip_type", i);
        s@orientation = prim(1, "orientation", i);
        //@Cd = set(1, 0, 0);
        // chip found
        return;
    }
}

int current_chip_id = i@chip_id;
string current_chip_type = s@chip_type;

if (current_chip_type == "STANDARD" || 
    current_chip_type == "MAIN_CHIP") {
    int nbrs[] = neighbours(0, @ptnum);
    foreach (int nbr; nbrs) {
        int nbr_chip_id = point(0, "chip_id", nbr);
        if (inpointgroup(0, "chip", nbr) == 0 || current_chip_id != nbr_chip_id) {
            @group_chip = 0;
            @group_pin = 1;
            //@Cd = set(1, 0, 0);
            break;
        }
    }
} else if (current_chip_type == "CYLINDER") {
    // THIS CURRENTLY ONLY SUPPORTS 3x3
    // Allow routing through cylinders
    // @group_chip = 0;

    int is_x_oriented = (s@orientation == "x");

    int nbrs[] = neighbours(0, @ptnum);

    int same_chip_count = 0;
    int internal_x_nbrs = 0;
    int internal_z_nbrs = 0;

    foreach (int nbr; nbrs) {
        // Only care about neighbors that belong to this exact chip
        if (inpointgroup(0, "chip", nbr) && point(0, "chip_id", nbr) == current_chip_id) {
            same_chip_count++;

            // Track which axis these internal neighbors sit on
            vector dir = abs(point(0, "P", nbr) - @P);
            if (dir.x > 0.01 && dir.z < 0.01) internal_x_nbrs++;
            if (dir.z > 0.01 && dir.x < 0.01) internal_z_nbrs++;
        }
    }

    // Only the middle edge point has exactly 5 internal neighbors
    if (same_chip_count == 5) {
        int is_pin = 0;

        if (is_x_oriented && internal_x_nbrs == 1) 
            is_pin = 1;        
        else if (!is_x_oriented && internal_z_nbrs == 1) 
            is_pin = 1;

        if (is_pin) {
            @group_chip = 0;
            @group_pin = 1;
            // @Cd = {1, 0, 0};
        }
    }
} else if (current_chip_type == "RAM") {
    int nbrs[] = neighbours(0, @ptnum);
    // Var whether RAM is x or z oriented
    int is_x_oriented = s@orientation == "x";
    foreach (int nbr; nbrs) {
        vector dir = abs(point(0, "P", nbr) - @P);
        int is_valid_axis = is_x_oriented ? (dir.z > 0.01 && dir.x < 0.01) : (dir.x > 0.01 && dir.z < 0.01);

        if (is_valid_axis) {
            if (!inpointgroup(0, "chip", nbr) || current_chip_id != point(0, "chip_id", nbr)) {
                @group_chip = 0;
                @group_pin = 1;
                //@Cd = {1, 0, 0};
                break;
            }
        }
    }
} else { // UNKNOWN CHIP TYPE
    @Cd = {1, 0, 0};
}

