    vector v1 = normalize(pos1 - @P);
    vector v2 = normalize(pos2 - @P);

    float dp = dot(v1, v2);

    if (abs(dp) < 0.001) {
        // 90-degree corner
        i@is_corner = 1;
        //@Cd = set(0, 0, 1);
    }

    vector centroid = detail(0, "P");
    vector mid_point = (pos1 + pos2) / 2.0;
    vector angle_vec = normalize(mid_point - @P);
    vector centroid_vec = normalize(centroid - @P);

    float direction = dot(angle_vec, centroid_vec);
    f@corner_direction = direction;
    if (direction > 0) {
        i@is_outward = 1;
    } else if (direction < 0) {
        i@is_inward = 1;
    }

    if(i@is_outward == 1 && i@is_corner == 1){
        i@is_outward_corner = 1;
        //@Cd = set(0, 1, 0);
    }

    if(i@is_inward == 1 && i@is_corner == 1){
        i@is_inward_corner = 1;
        int new_prim = addprim(0, "poly", boundary_neighs[0], boundary_neighs[1], @ptnum);
        setprimgroup(0, "filler", new_prim, 1);
        //@Cd = set(1, 0, 0);
    }
}

int pts[] = primpoints(0, @primnum);
