int min_dim1_ram_cell_size = chi("min_dim1_ram_cell_size");
int min_dim2_ram_cell_size = chi("min_dim2_ram_cell_size");
float distance_weight = chf("distance_weight");
float gcl = ch("../grid_cell_length");

float min_dim1 = min_dim1_ram_cell_size * gcl;
float min_dim2 = min_dim2_ram_cell_size * gcl;

vector size = getbbox_size(0, itoa(@primnum));

if ((size.x >= min_dim1 && size.z >= min_dim2) ||
    (size.x >= min_dim2 && size.z >= min_dim1)){
    // valid ram cell

    // calc irregularity
    float irregularity;
    if (size.x > size.z){
        irregularity = size.x / size.z;
    } else {
        irregularity = size.z / size.x;
    }

    // calc distance to main_chip
    vector pos_main_chip = point(1, "P", 0);
    float distance_to_main_chip = distance(@P, pos_main_chip);

    f@ram_value = irregularity + distance_to_main_chip * distance_weight;

    //@Cd = set(0, 0, f@ram_value);
}

int max_ram_count = chi("max_ram_count");
float rnd = rand(ch("../seed"));
int ram_width = chi("ram_width");

int max_possible_rams = min(max_ram_count, nprimitives(0) / ram_width);
i@ram_count = int((rnd * max_possible_rams) + 1);
int ram_prim_length = i@ram_count * ram_width;

int ram_start = int(rnd * (nprimitives(0) - ram_prim_length));

addprimattrib(0, "ram_id", -1);
for (int i = 0; i < ram_prim_length; i++) {
    int ram_id = i / ram_width;
    setprimattrib(0, "ram_id", ram_start + i, ram_id);
}

vector size = getbbox_size(0, itoa(@primnum));
float tol = ch("tolerance");
float gcl = ch("../grid_cell_length");

if((s@orientation == "x" && size.z < gcl - tol) ||
   (s@orientation == "z" && size.x < gcl - tol)){
    removeprim(0, @primnum, 1);
}

int iter = detail(1, "iteration");

// 1. get all valid pins into a single array
int pins[] = expandpointgroup(0, "pin");
int order[];
foreach(int pin; pins){
    push(order, int(point(0, "order", pin)));
}

// 2. select the start pin using the iteration number directly
int sorted_indices[] = argsort(order);
int start_pin = pins[sorted_indices[iter]];
i@start_pin = start_pin;

// (optional but recommended: skip if already connected from a previous iteration)
//if (point(0, "connected", start_pin) == 1) return;

// assign the start group
setpointgroup(0, "start_points", start_pin, 1);

// fetch the chip_id of the start pin so we don't route back into the same component
int start_chip_id = point(0, "chip_id", start_pin);

// 3. find all valid destination pins
foreach(int current_pin; pins) {

    // skip the start pin itself
    if (current_pin == start_pin) continue;

    // skip pins that are already successfully routed
    if (point(0, "connected", current_pin) == 1) continue;

    // skip pins that belong to the exact same chip
    int current_chip_id = point(0, "chip_id", current_pin);
    if (current_chip_id == start_chip_id) continue;

    // if the pin passes all checks, make it a valid target
    setpointgroup(0, "end_points", current_pin, 1);
}

int pins[] = expandpointgroup(0, "pin ^connected");

int pair_pin_a[], pair_pin_b[];
float distance_a_b[];
int pair_chip_id_a[], pair_chip_id_b[];

// 1. calculate all pairs
for(int i = 0; i < len(pins); i++){
    int pin_a = pins[i];
    int chip_id_a = point(0, "chip_id", pin_a);
    vector pos_a = point(0, "P", pin_a);

    for(int j = 0; j < len(pins); j++){
        int pin_b = pins[j];
        int chip_id_b = point(0, "chip_id", pin_b);

        if (chip_id_a != chip_id_b){
            vector pos_b = point(0, "P", pin_b); 
            float dist = distance(pos_a, pos_b);
            push(pair_pin_a, pin_a);
            push(pair_pin_b, pin_b);
            push(pair_chip_id_a, chip_id_a);
            push(pair_chip_id_b, chip_id_b);
            push(distance_a_b, dist);
        }
    }
}

// 2. sort by distance, prioritizing cylinders
int sorted_distance_indices[] = argsort(distance_a_b);
int cylinder_indices[], standard_indices[], main_indices[];

foreach(int i; sorted_distance_indices){
    // Fetch the chip type for BOTH pins in the pair
    string type_a = point(0, "chip_type", pair_pin_a[i]);
    string type_b = point(0, "chip_type", pair_pin_b[i]);

    // If EITHER pin is a cylinder, it goes into the cylinder queue
    if (type_a == "CYLINDER" || type_b == "CYLINDER"){
        push(cylinder_indices, i);
    } 
    // If no cylinder is involved, check if EITHER pin is a MAIN_CHIP
    else if (type_a == "MAIN_CHIP" || type_b == "MAIN_CHIP") {
        push(main_indices, i);
    } 
    // Otherwise, it's a standard connection
    else {
        push(standard_indices, i);
    }
}
append(cylinder_indices, main_indices);
append(cylinder_indices, standard_indices);
int sorted_indices[] = cylinder_indices;

// 3. assign the order attribute to the points
// default all pins to a high number in case they have no valid pairs
foreach(int p; pins){
    setpointattrib(0, "order", p, 99999);
}

int processed_pins[];
int current_order = 0;

foreach(int idx; sorted_indices){
    int pin_a = pair_pin_a[idx];
    int pin_b = pair_pin_b[idx];

    // Check if either pin is still looking for its shortest connection
    int a_unprocessed = find(processed_pins, pin_a) < 0;
    int b_unprocessed = find(processed_pins, pin_b) < 0;

    // If at least one pin in this pair hasn't been processed yet
    if (a_unprocessed || b_unprocessed){    
        // Assign order and mark pin_a as processed if it was free
        if (a_unprocessed){
            setpointattrib(0, "order", pin_a, current_order);
            push(processed_pins, pin_a);
            current_order++;
        }

        // Assign order and mark pin_b as processed if it was free
        if (b_unprocessed){
            setpointattrib(0, "order", pin_b, current_order);
            push(processed_pins, pin_b);
            current_order++;
        }
    }
}

setdetailattrib(0, "pin_count", len(pins));

// check if find shortest path generated a circuit
int circuit[] = expandprimgroup(1, "circuit");

if (len(circuit) > 0){
    // sucessfully connected
    int start_point = expandpointgroup(0, "start_point")[0];
    int end_point = expandpointgroup(0, "end_point")[0];
    int source_pin = point(0, "source_pin", start_point);
    int dest_pin = point(0, "dest_pin", end_point);
    int pt_start = findattribval(0, "point", "source_pin", source_pin, 0);
    int pt_end = findattribval(0, "point", "dest_pin", dest_pin, 0);
    setpointgroup(0, "connected", pt_start, 1);
    setpointgroup(0, "connected", pt_end, 1);
    //setpointattrib(0, "Cd", pt_start, set(1, 0, 0));
    //setpointattrib(0, "Cd", pt_end, set(1, 0, 0));
}

int max_ram_length = chi("max_ram_length");
float gcl = ch("../grid_cell_length");

float absolute_max_ram_length = max_ram_length * gcl;
vector size = getbbox_size(0);

if (s@orientation == "x") {
    v@bricker_size = set(min(absolute_max_ram_length, size.x), 1, size.z * 2);
} else if (s@orientation == "z") {
    v@bricker_size = set(size.x * 2, 1, min(absolute_max_ram_length, size.z));
}

float gcl = ch("../grid_cell_length");
vector size = getbbox_size(0);

s@orientation = (size.x > size.z) ? "x" : "z";

if(s@orientation == "x") {
    v@bricker_size = set(size.x + 0.1, 0, gcl);
} else if(s@orientation == "z") {
    v@bricker_size = set(gcl, 0, size.z + 0.1);
}

// Find find source and dest pin in grid
int guide_line[] = primpoints(1, 0);
int source_pin = point(1, "source_pin", guide_line[0]);
int dest_pin = point(1, "dest_pin", guide_line[0]);
// Add the points to start and end group
int start_point = findattribval(0, "point", "source_pin", source_pin);
int end_point = findattribval(0, "point", "source_pin", dest_pin);
setpointgroup(0, "start_point", start_point, 1);

setpointgroup(0, "end_point", end_point, 1);

// check if find shortest path generated a circuit
int circuit[] = expandprimgroup(1, "circuit");

if (len(circuit) > 0){
    // sucessfully connected
    int start_point = expandpointgroup(0, "start_point")[0];
    int end_point = expandpointgroup(0, "end_point")[0];
    int source_pin = point(0, "source_pin", start_point);
    int dest_pin = point(0, "dest_pin", end_point);
    int pt_start = findattribval(0, "point", "source_pin", source_pin, 0);
    int pt_end = findattribval(0, "point", "dest_pin", dest_pin, 0);
    setpointgroup(0, "connected", pt_start, 1);
    setpointgroup(0, "connected", pt_end, 1);
    //setpointattrib(0, "Cd", pt_start, set(1, 0, 0));
    //setpointattrib(0, "Cd", pt_end, set(1, 0, 0));
}

int pins[] = expandpointgroup(0, "pin ^connected");

int pair_pin_a[];
int pair_pin_b[];
float distance_a_b[];
int pair_chip_id_a[];
int pair_chip_id_b[];

for(int i = 0; i < len(pins); i++){
    int pin_a = pins[i];
    int chip_id_a = point(0, "chip_id", pin_a);
    vector pos_a = point(0, "P", pin_a);

    for(int j = i + 1; j < len(pins); j++){
        int pin_b = pins[j];
        int chip_id_b = point(0, "chip_id", pin_b);

        if (chip_id_a != chip_id_b){
            vector pos_b = point(0, "P", pin_b); 
            float dist = distance(pos_a, pos_b);
            push(pair_pin_a, pin_a);
            push(pair_pin_b, pin_b);
            push(pair_chip_id_a, chip_id_a);
            push(pair_chip_id_b, chip_id_b);
            push(distance_a_b, dist);
        }
    }
}

// first sort by distances
int sorted_distance_indices[] = argsort(distance_a_b);
// then sort by chip type (cylinders first)
int cylinder_indices[];
int standard_indices[];
foreach(int i; sorted_distance_indices){
    string source_chip_type = point(0, "chip_type", pair_pin_a[i]);
    if (source_chip_type == "CYLINDER"){
        push(cylinder_indices, i);
    } else {
        push(standard_indices, i);
    }
}
append(cylinder_indices, standard_indices);
int sorted_indices[] = cylinder_indices;

int taken[];
resize(taken, npoints(0));

addpointattrib(0, "dest_pin", -1);
addpointattrib(0, "source_pin", -1);

string connected_chip_pairs[];

int path_count = 0;
foreach(int idx; sorted_indices){
    int pin_a = pair_pin_a[idx];
    int pin_b = pair_pin_b[idx];

    if (taken[pin_a] == 1 || taken[pin_b] == 1){
        continue;
    }

    string chip_type_a = point(0, "chip_type", pin_a);
    string chip_type_b = point(0, "chip_type", pin_b);
    int current_chip_a = point(0, "chip_id", pin_a);
    int current_chip_b = point(0, "chip_id", pin_b);
    int min_chip = min(current_chip_a, current_chip_b);
    int max_chip = max(current_chip_a, current_chip_b);
    string pair_id = sprintf("%d-%d", min_chip, max_chip);

    // NEW: if this chip pair is already in the array, skip this connection
    int both_cylinder = (chip_type_a == "CYLINDER") && (chip_type_b == "CYLINDER");
    if (both_cylinder && find(connected_chip_pairs, pair_id) >= 0){
        continue;
    }

    taken[pin_a] = 1;
    taken[pin_b] = 1;

    push(connected_chip_pairs, pair_id);

    setpointattrib(0, "source_pin", pin_a, pin_a);
    setpointattrib(0, "source_pin", pin_b, pin_b);
    setpointattrib(0, "dest_pin", pin_a, pin_b);
    setpointattrib(0, "dest_pin", pin_b, pin_a);

    int guide = addprim(0, "polyline", pin_a, pin_b);
    // shorter distance -> process first (lower order)
    setprimattrib(0, "order_priority", guide, path_count);
    setprimgroup(0, "guide_line", guide, 1);
    path_count++;
}

setdetailattrib(0, "num_paths", path_count);

vector n = normalize(chv("dir"));
float tolerance = ch("tolerance");

int pts[] = neighbours(0, @ptnum);
foreach (int pt; pts) {
    if (@ptnum < pt) {
        vector p = point (0, "P", pt);
        vector dir = normalize ( @P - p );
        if (1 - abs(dot(dir, n)) <= tolerance)
            setedgegroup(0, "selected_edges", @ptnum, pt, 1);
    }
}

float tolerance = ch("tolerance");

int pts[] = neighbours(0, @ptnum);
if(len(pts) == 2){
    vector p0 = point(0, "P", pts[0]);
    vector p1 = point(0, "P", pts[1]);

    vector dir0 = normalize(p0 - @P);
    vector dir1 = normalize(p1 - @P);

    if (1- abs(dot(dir0, dir1)) < tolerance){
        setpointgroup(0, "inline", @ptnum, 1);
    }
}
